// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address _migrator) public {
        vm.assume(_migrator != address(0));
        vm.prank(address(this));
        c.setMigrator(_migrator);
        c.addReward(address(1));
        assertTrue(c.migrator() == _migrator);
    }
}

